import { readFileSync } from "node:fs";
import { generateSystemPrompt } from "@openuidev/lang-core";

import type { OpenUIComponentSpec } from "./types.js";

// The component library spec is generated by `openui generate` from @openuidev/react-ui/genui-lib and shipped with the package.
const { promptOptions, ...base } = JSON.parse(readFileSync(new URL("../../openui-spec.json", import.meta.url), "utf8")) as {
  promptOptions: unknown;
  components: Record<string, { signature: string; description: string }>;
  componentGroups: Array<{ name: string; components: string[]; notes?: string[] }>;
  [key: string]: unknown;
};

/** `CronjobList(filter?: string)` from a plugin's positional prop list. */
export function signatureOf(spec: OpenUIComponentSpec): string {
  return `${spec.name}(${spec.props.map((prop) => `${prop.name}${prop.optional ? "?" : ""}: ${prop.type}`).join(", ")})`;
}

/** System prompt that makes the model answer the web chat in OpenUI Lang, including the components installed plugins provide. */
export function buildOpenUIInstructions(plugins: readonly OpenUIComponentSpec[] = []): string {
  const names = plugins.map((spec) => spec.name);
  const components = Object.fromEntries(Object.entries(base.components).map(([name, entry]) => [
    name,
    // Plugin components may sit wherever a Stack can.
    names.length && entry.signature.includes("| Stack)") ? { ...entry, signature: entry.signature.replace("| Stack)", `| Stack | ${names.join(" | ")})`) } : entry,
  ]));
  for (const spec of plugins) components[spec.name] = { signature: signatureOf(spec), description: spec.description };
  const componentGroups = names.length
    ? [...base.componentGroups, { name: "Agent OS", components: names, notes: ["- These render live data from the running Agent OS plugins and come with their own controls; prefer them over hand-built Tables for the same information.", ...plugins.flatMap((spec) => spec.props.filter((prop) => prop.description).map((prop) => `- ${spec.name} ${prop.name}: ${prop.description}`))] }]
    : base.componentGroups;
  return [
    generateSystemPrompt({ cloud: false, library: { ...base, components, componentGroups }, promptOptions } as unknown as Parameters<typeof generateSystemPrompt>[0]),
    "You may call tools first; only the final reply must be openui-lang, with no code fences around it.",
  ].join("\n\n");
}
